{
  "name": "任意波形发生器",
  "name_en": "Arbitrary Waveform Generator",
  "manufacturer": "",
  "description": "任意波形发生器可输出用户定义的电压波形，并可通过查找表或码字索引快速调用不同脉冲。它常用于实验室中的脉冲激励、时序控制以及需要精确波形合成的测量系统。",
  "description_en": "An arbitrary waveform generator outputs user-defined voltage waveforms and can rapidly call up different pulses through lookup tables or codeword indexing. It is commonly used in laboratories for pulse excitation, timing control, and measurement systems that require precise waveform synthesis.",
  "tag_hints": [
    "arbitrary waveform generation",
    "waveform lookup table",
    "codeword addressing",
    "pulse generation",
    "DIO-triggered waveform selection",
    "timing control"
  ],
  "actions": [
    {
      "action_name": "auto-set_default_lutmap",
      "description": "设置默认波形查找表映射。",
      "description_en": "Set the default waveform lookup-table mapping."
    },
    {
      "action_name": "auto-generate_standard_waveforms",
      "description": "生成标准波形集合。",
      "description_en": "Generate the standard waveform set."
    },
    {
      "action_name": "auto-load_waveform_onto_AWG_lookuptable",
      "description": "将单个波形加载到AWG查找表。",
      "description_en": "Load a single waveform into the AWG lookup table."
    },
    {
      "action_name": "auto-load_waveforms_onto_AWG_lookuptable",
      "description": "将全部映射波形加载到AWG查找表。",
      "description_en": "Load all mapped waveforms into the AWG lookup table."
    },
    {
      "action_name": "auto-render_wave",
      "description": "显示波形图。",
      "description_en": "Display the waveform plot."
    },
    {
      "action_name": "auto-render_wave_PSD",
      "description": "显示波形的功率谱密度图。",
      "description_en": "Display the waveform power spectral density plot."
    },
    {
      "action_name": "auto-time_to_sample",
      "description": "将时间换算为对应的采样点索引。",
      "description_en": "Convert a time value to the corresponding sample index."
    },
    {
      "action_name": "auto-make",
      "description": "更新AWG上的待处理查找表波形，必要时停止并重启设备输出。",
      "description_en": "Update pending lookup-table waveforms on the AWG, stopping and restarting output if needed."
    }
  ]
}

